firstLabel:
type User {
  id: ID!
  age: Int!
  name: String!
  image: UserImage!
  book: Book!
}

type Author {
  _id: ID!
  name: String!
  book: Book!
}

union UserImage = UserImageSolidColor | UserImageURL

type UserImageSolidColor {
  color: String!
}

type UserImageURL {
  url: String!
}

scalar Date

interface Book {
  id: ID!
  title: String
  publishedAt: Date
}

type TextBook implements Book {
  id: ID!
  title: String
  publishedAt: Date
  text: String
}

type ColoringBook implements Book {
  id: ID!
  title: String
  publishedAt: Date
  colors: [String]
}

type Query {
  viewer: User!
  userById(id: ID!): User!
  author: Author!
}

type Mutation {
  changeViewerName(newName: String!): User!
}

